// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)

const KEYWORDS = [
  '人工智能', 'AI', '大模型', 'LLM', '基础模型', 'foundation model',
  'Agent', '代理', '多模态', '多模态', 'Transformer',
  'AIGC', '生成式', '生成模型',
