  'arxiv', 'NeurIPS', 'ICLR', 'ICML', 'CVPR', 'ACL', 'EMNLP', 'KDD',
  '论文', '研究', '实验', 'SOTA', 'state-of-the-art'
];

// ========================================
// 核心信息源配置：重点关注的媒体来源
// ========================================
const CORE_SOURCES = ['量子位', '机器之心', '新智元'];

// ========================================
// 时间新鲜度阈值配置（单位：小时）
// ========================================
const FRESH_6H = 6;   // 6小时内视为超新鲜
const FRESH_24H = 24; // 24小时内视为新鲜

// ========================================
// 工具函数：将数值限制在指定范围内
// ========================================
function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

// ========================================
// (1) 相关性评分函数：评估内容与账号定位的相关程度
// 评分范围：0-25分
// ========================================
function calcRelevance(title, summary, source_name) {
  // 将标题和摘要合并为小写文本，便于关键词匹配
  const text = `${title} ${summary}`.toLowerCase();
  let score = 0;
  let hits = 0;

  // 统计命中的关键词数量
  KEYWORDS.forEach(k => {
    if (text.includes(k.toLowerCase())) hits++;
  });

  // 根据关键词命中数量分配基础分数
  if (hits === 0) {
    // 完全不命中领域关键词，认为价值很低
    score = 2;
  } else if (hits === 1) {
    score = 10;
  } else if (hits === 2) {
    score = 15;
  } else if (hits >= 3) {
    score = 20;
  }

  // 如果来源是重点关注的媒体，额外加分
  if (CORE_SOURCES.includes(source_name)) {
    score += 5;
  }

  // 确保分数在0-25范围内
  return clamp(score, 0, 25);
}

// ========================================
// (2) 时效性评分函数：评估新闻的新鲜度和热度
// 评分范围：0-25分
// ========================================
function calcTimeliness(pubDate) {
  // 如果没有发布日期，返回0分
  if (!pubDate) return 0;
  // 计算发布时间与当前时间的差值（小时）
  const diffHours = ($now.toMillis() - DateTime.fromFormat(pubDate, 'yyyy.MM.dd HH:mm:ss').toMillis()) / (1000 * 60 * 60);
  let score = 0;

  // 根据时间差分配分数，越新鲜分数越高
  if (diffHours <= FRESH_6H) {
    score = 22; // 超新鲜内容（6小时内）
  } else if (diffHours <= FRESH_24H) {
    score = 18; // 新鲜内容（24小时内）
  } else if (diffHours <= 72) {
    score = 12; // 较新内容（3天内）
  } else if (diffHours <= 168) {
    score = 6;  // 一周内内容
  } else {
    score = 2;  // 旧闻，但不给绝对0分
  }

  // 确保分数在0-25范围内
  return clamp(score, 0, 25);
}

// ========================================
// (3) 深度与新颖性评分函数：评估内容的深度和技术含量
// 评分范围：0-25分
// ========================================
function calcDepth(title, summary, source_type) {
  // 合并标题和摘要用于分析
  const text = `${title} ${summary}`;
  let score = 0;

  // 检测研究/技术/论文相关的深度信号词
  const depthWords = [
    '论文', '研究', '实验', '架构', '算法', '原理', '技术细节',
    '系统', '框架', '模型结构', '训练方法', '对比实验', 'benchmark', 'SOTA'
  ];
  if (depthWords.some(w => text.includes(w))) score += 10;

  // 检测长文/深度分析信号词
  const longformWords = ['长文', '深度', '完全指南', '全解析', '详解', '拆解'];
  if (longformWords.some(w => text.includes(w))) score += 5;

  // 摘要较长通常意味着信息量更大
  if (summary && summary.length > 300) score += 5;

  // 来源类型为学术机构/官方博客类，额外加分
  if (source_type === '学术机构' || source_type === '官方博客') {
    score += 5;
  }

  // 确保分数在0-25范围内
  return clamp(score, 0, 25);
}

// ========================================
// (4) 影响力评分函数：评估对行业格局/技术路线/商业落地的重要性
// 评分范围：0-25分
// ========================================
function calcImpact(title, summary, source_type) {
  // 合并标题和摘要用于分析
  const text = `${title} ${summary}`;
  let score = 0;

  // 检测商业大事件信号词（融资/并购/上市等）
  const impactWordsBusiness = [
    '融资', '收购', '并购', '上市', 'IPO', '估值', '破产', '倒闭',
    '裁员', '大裁员'
  ];
  if (impactWordsBusiness.some(w => text.includes(w))) score += 8;

  // 检测技术/产品重大事件信号词
  const impactWordsTech = [
    '发布', '开源', '重大更新', 'v1.0', 'v2.0', '2.0', '里程碑',
    '突破', '颠覆', '革命性', '大幅提升', 'state-of-the-art', 'SOTA'
  ];
  if (impactWordsTech.some(w => text.includes(w))) score += 8;

  // 检测监管/政策/标准相关信号词
  const impactWordsPolicy = [
    '监管', '法规', '政策', '合规', '指南', '禁令', '标准', '草案'
  ];
  if (impactWordsPolicy.some(w => text.includes(w))) score += 8;

  // 检测是否涉及头部玩家/巨头公司
  const bigPlayers = [
    'OpenAI', 'Google', 'DeepMind', 'Anthropic', 'Meta', '微软',
    'Microsoft', 'NVIDIA', '英伟达', '亚马逊', 'Amazon',
    '阿里', '腾讯', '字节', '百度', '特斯拉', 'Tesla'
  ];
  if (bigPlayers.some(b => text.includes(b))) score += 5;

  // 来源类型为公众号/政策机构/官方博客，额外加分
  if (source_type === '公众号' || source_type === '政策机构' || source_type === '官方博客') {
    score += 4;
  }

  // 确保分数在0-25范围内
  return clamp(score, 0, 25);
}

// ========================================
// 机器标签推断函数：根据内容自动识别相关标签
// ========================================
function inferBasicTags(text) {
  const tags = [];

  // 根据关键词匹配添加相应标签
  if (text.includes('大模型') || text.includes('LLM') || text.includes('基础模型')) tags.push('大模型');
  if (text.includes('Agent') || text.includes('代理')) tags.push('Agent');
  if (text.includes('多模态')) tags.push('多模态');
  if (text.includes('算力') || text.includes('GPU') || text.includes('芯片') || text.includes('半导体')) tags.push('算力/芯片');
  if (text.includes('云') || text.includes('云计算')) tags.push('云/基础设施');
  if (text.includes('机器人') || text.includes('自动驾驶') || text.includes('无人车') || text.includes('无人机')) tags.push('机器人/自动驾驶');
  if (text.includes('监管') || text.includes('政策') || text.includes('合规')) tags.push('AI治理/政策');
  if (text.toLowerCase().includes('arxiv') || text.includes('论文') || text.includes('研究')) tags.push('论文/科研');

  // 如果没有匹配到任何标签，添加默认标签
  if (tags.length === 0) tags.push('综合AI资讯');

  // 去重并返回标签数组
  return Array.from(new Set(tags));
}

// ========================================
// 一级赛道推断函数：识别内容所属的主要技术赛道
// ========================================
function inferPrimaryTrack(text) {
  // 按优先级匹配赛道，先匹配到的优先返回
  if (text.includes('大模型') || text.includes('LLM') || text.includes('基础模型')) return '大模型/基础模型';
  if (text.includes('Agent') || text.includes('代理')) return 'Agent/自动化';
  if (text.includes('多模态')) return '多模态/视觉/语音';
  if (text.includes('算力') || text.includes('GPU') || text.includes('芯片') || text.includes('半导体')) return '算力/芯片';
  if (text.includes('云') || text.includes('云计算') || text.includes('边缘计算')) return '云/基础设施';
  if (text.includes('机器人') || text.includes('自动驾驶') || text.includes('无人车') || text.includes('无人机')) return '机器人/自动驾驶';
  if (text.includes('监管') || text.includes('政策') || text.includes('合规') || text.includes('伦理')) return 'AI治理/政策';
  if (text.toLowerCase().includes('arxiv') || text.includes('论文') || text.includes('研究')) return '论文/科研';

  // 默认赛道
  return '综合AI资讯';
}

// ========================================
// 主流程：获取输入数据并执行评分
