// 计算四个维度的评分
const relevance = calcRelevance(title, summary, source_name);
const timeliness = calcTimeliness(pubDate);
const depth = calcDepth(title, summary, source_type);
const impact = calcImpact(title, summary, source_type);

// 执行机器标签和一级赛道推断
const text = `${title} ${summary}`;
const basicTags = inferBasicTags(text);
const primaryTrack = inferPrimaryTrack(text);

// 计算发布时效性（距今多少小时）
let pubHoursAgo = null;
if (pubDate) {
  // 计算发布时间与当前时间的小时差
  const diffHours = ($now.toMillis() - DateTime.fromFormat(pubDate, 'yyyy.MM.dd HH:mm:ss').toMillis()) / (1000 * 60 * 60);
  // 四舍五入到整数小时
  pubHoursAgo = Math.round(diffHours);
}

// ========================================
// 返回处理结果
