    // 机器推断的一级赛道
    primary_track: primaryTrack,
    // 发布时效性
    pub_hours_ago: pubHoursAgo,
  },
};

// ========================================
// 合并规则层 4 维度 (relevance/timeliness/depth/impact) 与 AI 微调与潜力分
// ========================================

// Author:@南哥AGI研习社 (B站 or YouTube 搜索“南哥AGI研习社”)

// ========================================
// 工具函数：将数值限制在指定范围内
// ========================================
function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

// ========================================
// 四维度权重配置：用于加权计算各维度的重要性
// 注意：总和不需要等于 1，后续会进行归一化处理
// ========================================
const WEIGHTS = {
  relevance: 1.2,  // 领域相关度权重
  timeliness: 1.0, // 时效性权重
  depth: 1.0,      // 深度/新颖性权重
  impact: 1.3      // 行业影响力权重
};

// ========================================
// AI 潜力分在总分中的占比配置
// AI_WEIGHT = 0.2 表示 AI 潜力占 20%，四维度合计占 80%
// ========================================
const AI_WEIGHT = 0.2;

// ========================================
// 紧急预警阈值配置
// 用于判断是否需要触发突发新闻预警
// ========================================
const URGENT_ALERT_CONFIG = {
  SCORE_THRESHOLD: 85,      // 最终得分阈值：≥85分触发预警
  TIMELINESS_THRESHOLD: 20, // 时效性阈值：≥20分触发预警
  IMPACT_THRESHOLD: 20      // 影响力阈值：≥20分触发预警
};

// ========================================
// 获取规则层的打分结果
// ========================================
const rule = $('基于规则打分').first().json.rule_scores || {};
// ========================================
// 获取 AI 层的输出结果
// ========================================
const ai = $input.first().json.output;
// 获取 AI 层对四维度的微调分数
const adj = ai.adjust_scores || {};

// ========================================
// (1) 合并四个维度分：规则基础分 + AI 微调分
// 每个维度的有效范围：0~25 分
// ========================================

// 相关性得分 = 规则层相关性分 + AI 微调值，限制在 0-25 范围内
const relevance = clamp((rule.relevance || 0) + (adj.relevance_adjust || 0), 0, 25);

// 时效性得分 = 规则层时效性分 + AI 微调值，限制在 0-25 范围内
const timeliness = clamp((rule.timeliness || 0) + (adj.timeliness_adjust || 0), 0, 25);

// 深度得分 = 规则层深度分 + AI 微调值，限制在 0-25 范围内
const depth = clamp((rule.depth || 0) + (adj.depth_adjust || 0), 0, 25);

// 影响力得分 = 规则层影响力分 + AI 微调值，限制在 0-25 范围内
const impact = clamp((rule.impact || 0) + (adj.impact_adjust || 0), 0, 25);

// 将四个维度得分封装为对象
const factor_scores = { relevance, timeliness, depth, impact };

// ========================================
// (2) 将四维度进行加权平均，并映射到 0~100 分制
// ========================================

// 获取相关性权重
const wRel = WEIGHTS.relevance || 1;

// 获取时效性权重
const wTime = WEIGHTS.timeliness || 1;

// 获取深度权重
const wDepth = WEIGHTS.depth || 1;

// 获取影响力权重
const wImpact = WEIGHTS.impact || 1;

// 计算权重总和，用于归一化
const wSum = wRel + wTime + wDepth + wImpact;

// 计算加权平均分：结果范围 0~25
const weightedFactorAvg =
  (relevance * wRel + timeliness * wTime + depth * wDepth + impact * wImpact) / wSum;

// 将加权平均分映射到 0~100 分制（乘以 4）
const fourFactorScore = weightedFactorAvg * 4;

// ========================================
// (3) 处理 AI 潜力分：从 0~10 映射到 0~100
// ========================================

// 获取 AI 潜力原始分数（0~10）
const ai_potential_score = ai.ai_potential_score || 0;

// 将 AI 潜力分映射到 0~100 分制（乘以 10），并限制在有效范围内
const aiScore100 = clamp(ai_potential_score * 10, 0, 100);

// ========================================
// (4) 计算最终总分：四维度得分 + AI 潜力得分的加权组合
// ========================================

// 计算四维度在总分中的占比（80%）
const factorPortion = (1 - AI_WEIGHT);

// 最终得分 = 四维度得分 × 80% + AI 潜力得分 × 20%
let final_score = fourFactorScore * factorPortion + aiScore100 * AI_WEIGHT;

// 确保最终得分在 0~100 范围内
final_score = clamp(final_score, 0, 100);

// ========================================
// (5) 根据最终得分确定优先级等级
// 可以按需调整阈值
// ========================================

// 初始化优先级为"低"
let priority = '低';

// 根据分数区间设置优先级
if (final_score >= 80) priority = '必做';       // 80分以上：必做
else if (final_score >= 60) priority = '高';    // 60-79分：高优先级
else if (final_score >= 40) priority = '中';    // 40-59分：中优先级
// 40分以下：保持"低"优先级

// ========================================
// (6) 获取竞争度和变现潜力，用于决定执行槽位
// ========================================

// 获取内容竞争度（低/中/高）
const competition_level = ai.competition_level || '低';

// 获取变现潜力（低/中/高）
const monetization_potential = ai.monetization_potential || '低';

// ========================================
// 根据综合条件判断执行槽位
// ========================================

// 初始化执行槽位为"观察"
let execution_slot = '观察';

// 判断逻辑：高分且低竞争 → 必做主线
if (final_score >= 80 && (competition_level === '低' || competition_level === '中')) {
  execution_slot = '必做主线';
} 
// 判断逻辑：较高分但高竞争 → 高优先（需做差异化深度）
else if (final_score >= 70 && competition_level === '高') {
  execution_slot = '高优先';
} 
// 判断逻辑：中高分且高变现潜力 → 高优先（偏商业价值）
else if (final_score >= 60 && monetization_potential === '高') {
  execution_slot = '高优先';
} 
// 判断逻辑：中等分数 → 中优先
else if (final_score >= 40) {
  execution_slot = '中优先';
}
// 其他情况：保持"观察"状态

// ========================================
// 生成执行策略详情文案
// 根据执行槽位、竞争度、变现潜力等因素，生成具体的执行建议
// ========================================
function generateStrategyDetail(params) {
  const { competition_level, monetization_potential, execution_slot, depth, impact } = params;

  let strategy = '';

  // 策略 1: 必做主线 - 抢占先发优势
  if (execution_slot === '必做主线') {
    if (competition_level === '低' || competition_level === '中') {
      strategy = `🎯 抢占先发优势策略
• 响应时间: 2 小时内完成初稿
• 资源配置: 主编+资深编辑
• 内容方向: 独家深度解读，建立话题权威
• 分发策略: 全平台同步首发，SEO 优化
• 预期效果: 占据该话题搜索前 3 位`;
    } else {
      // 必做但竞争度高的情况
      strategy = `⚔️ 红海突围策略  
• 响应时间: 4 小时内（非最快，但要最深）
• 资源配置: 技术主笔+数据分析
• 内容方向: 技术拆解/性能对比/独家采访，做差异化
• 分发策略: 长文深度为主，配合短视频二次传播
• 预期效果: 后发制人，成为该话题权威解读`;
    }
  }

  // 策略 2: 高优先级 - 差异化深度策略
  else if (execution_slot === '高优先' && competition_level === '高') {
    strategy = `🔍 差异化深度策略
• 响应时间: 当日完成
• 资源配置: 资深编辑
• 内容方向: 全网已有快讯，需切独特角度（技术原理/行业影响/对比评测）
• 分发策略: 避开快讯时段，做深度长文
• 预期效果: 在已有报道基础上建立专业形象`;
  }

  // 策略 3: 高优先级 - 商业价值最大化策略
  else if (execution_slot === '高优先' && monetization_potential === '高') {
    strategy = `💰 商业价值最大化策略
• 响应时间: 2 天内
• 资源配置: 编辑+商务协同
• 内容方向: 嵌入企业案例/工具推荐/实战指南
• 变现路径: 咨询线索/付费报告/课程引流/企业服务合作
• 预期效果: 直接产生商业转化，ROI 可追踪`;
  }

  // 策略 4: 中优先 - 常规覆盖策略
  else if (execution_slot === '中优先') {
    strategy = `📝 常规覆盖策略
• 响应时间: 本周完成
• 资源配置: 常规编辑
• 内容方向: 标准流程，保持更新节奏
• 分发策略: 主站发布，社交媒体同步
• 预期效果: 日常流量贡献`;
  }

  // 策略 5: 观察状态 - 待发展策略
  else {
    strategy = `👀 观察待发展策略
• 当前建议: 暂不投入资源
• 收藏原因: ${depth >= 15 ? '有一定深度潜力，' : ''}${impact >= 12 ? '可能后续发酵' : '当前价值不足'}
• 触发条件: 若事态发展/竞争度降低/出现独家角度，系统自动提权
• 操作: 加入"观察池"视图，每周复查`;
  }

  return strategy;
}

// ========================================
// 调用策略生成函数，获取详细执行策略文案
// ========================================
const execution_strategy_detail = generateStrategyDetail({
  competition_level: competition_level,
  monetization_potential: monetization_potential,
  execution_slot: execution_slot,
  depth: depth,
  impact: impact
});

// ========================================
// 紧急预警判断逻辑
// 根据最终得分、时效性、影响力、执行槽位等综合条件判断是否需要触发预警
// ========================================
const urgent_alert = 
  final_score >= URGENT_ALERT_CONFIG.SCORE_THRESHOLD &&
  timeliness >= URGENT_ALERT_CONFIG.TIMELINESS_THRESHOLD &&
  (impact >= URGENT_ALERT_CONFIG.IMPACT_THRESHOLD || execution_slot === '必做主线');

// ========================================
// 返回处理结果
// ========================================
return {
  json: {
    // 存储四个维度的最终得分（合并规则层与 AI 微调后）
    factor_scores: factor_scores,

    // 最终总分（0-100）和 AI 潜力原始分（0-10）
    final_score: Math.round(final_score),
    ai_potential_score: ai_potential_score,

    // 分类与标签信息
    // 优先使用 AI 层结果，如果缺失则使用规则层兜底
    primary_track: ai.primary_track || $('基于规则打分').first().json.primary_track || '综合AI资讯',
    content_type: ai.content_type || '快讯',
    monetization_potential: monetization_potential,
    machine_tags: ai.machine_tags || $('基于规则打分').first().json.basic_tags || [],
    competition_level: competition_level,
    execution_hint: ai.execution_hint || '',
    execution_slot: execution_slot,
    priority: priority,

    // 执行策略详情：包含具体的执行建议和打法指导
    execution_strategy_detail: execution_strategy_detail,

    // ========================================
    // 紧急预警标记
    // true 表示需要立即触发预警通知（推送到飞书）
    // ========================================
    urgent_alert: urgent_alert
  },
};

